"""在 PATH 上把命令名解析成磁盘路径。

Windows 上「命令名」通常不带扩展名，例如 ``where``、``git``、``build``。
Shell 之所以能找到它们，是因为按 :envvar:`PATHEXT` 里声明的扩展名顺序
逐个试探。任何要自己启动外部程序的工具都必须照做，否则只能看见 ``.exe``。

搜索顺序与 ``cmd.exe`` 一致：外层遍历 :envvar:`PATH` 里的目录，内层按
:envvar:`PATHEXT` 声明的顺序试扩展名。名字本身已经带着 PATHEXT 里的扩展名
时（``tool.exe``、``direct.CMD``）只按原样查找，绝不叠加成 ``tool.exe.exe``。
"""

import os

from .errors import CommandNotFound

#: 找不到 PATHEXT 时使用的兜底扩展名。
EXECUTABLE_EXTENSIONS = (".exe",)


def search_dirs():
    """返回 PATH 中需要搜索的目录列表。"""
    raw = os.environ.get("PATH", "")
    return [d for d in raw.split(os.pathsep) if d]


def executable_extensions():
    """返回按优先级排列的可执行扩展名。

    优先使用环境变量 :envvar:`PATHEXT`，并保持其中声明的**顺序**与写法；
    它缺失（或为空）时才退回内置兜底值 :data:`EXECUTABLE_EXTENSIONS`。
    """
    raw = os.environ.get("PATHEXT") or ""

    extensions = []
    for token in raw.split(os.pathsep):
        token = token.strip()
        if not token:
            continue
        if not token.startswith("."):
            # 容错：PATHEXT 里写成 "EXE" 时补上前导点。
            token = "." + token
        extensions.append(token)

    if not extensions:
        return EXECUTABLE_EXTENSIONS
    return tuple(extensions)


def candidate_names(name, extensions=None):
    """列出解析 ``name`` 时在单个目录内依次试探的文件名。

    * ``name`` 不带扩展名（``hello``）：按 ``extensions`` 的顺序拼接，
      于是 PATHEXT 的先后直接决定命中哪一个。
    * ``name`` 已经带着 PATHEXT 声明的扩展名（``direct.CMD``、``tool.exe``）：
      只试它自己，不再叠加扩展名。
    * ``name`` 带着别的扩展名（``python3.12``、``gcc-13.2``）：先试原样，
      再按顺序补扩展名——与 ``cmd.exe`` 的行为一致。
    """
    if extensions is None:
        extensions = executable_extensions()
    extensions = tuple(extensions)

    ext = os.path.splitext(name)[1]
    if not ext:
        return tuple("%s%s" % (name, e) for e in extensions)

    known = set(os.path.normcase(e) for e in extensions)
    if os.path.normcase(ext) in known:
        return (name,)
    return (name,) + tuple("%s%s" % (name, e) for e in extensions)


def _directories_for(name):
    """``name`` 需要搜索的目录列表。

    带路径分隔符的名字（``.\\build``、``C:\\tools\\x``）只按给定位置解析，
    不再跑遍 PATH。
    """
    if os.path.dirname(name):
        return [""]
    return search_dirs()


def _real_case(directory, filename):
    """返回 ``filename`` 在磁盘上的真实写法（Windows 文件系统不区分大小写）。

    拼出来的候选名用的是 PATHEXT 里的大小写，磁盘上可能是另一种写法；
    这里换成真实写法，免得调用方拿到与文件系统不一致的路径。
    """
    if os.name != "nt" or not filename:
        return filename
    try:
        with os.scandir(directory or ".") as entries:
            wanted = os.path.normcase(filename)
            for entry in entries:
                if os.path.normcase(entry.name) == wanted:
                    return entry.name
    except OSError:
        pass
    return filename


def resolve(name):
    """把 ``name`` 解析成磁盘上的绝对路径。

    找不到时抛 :class:`CommandNotFound`。
    """
    if not name:
        raise CommandNotFound(name)

    candidates = candidate_names(name, executable_extensions())

    seen = set()
    for directory in _directories_for(name):
        key = os.path.normcase(directory)
        if key in seen:
            continue
        seen.add(key)

        for candidate in candidates:
            full = os.path.join(directory, candidate)
            if not os.path.isfile(full):
                continue
            head, tail = os.path.split(full)
            return os.path.abspath(os.path.join(head, _real_case(head, tail)))

    raise CommandNotFound(name)

"""运行已经解析出来的命令。

``.bat`` / ``.cmd`` 是批处理脚本，不是 PE 可执行文件：把它们直接交给
CreateProcess 会得到 WinError 193（``%1 不是有效的 Win32 应用程序``）。
Windows 的要求是启动命令解释器 ``cmd.exe``，把 ``/c`` 和脚本名传给它；
解释器执行完会把脚本的退出码原样带回来。
"""

import os
import subprocess

from .errors import CommandNotFound
from .resolve import resolve

#: 必须经由命令解释器启动的脚本扩展名（小写，含前导点）。
INTERPRETER_EXTENSIONS = (".bat", ".cmd")

#: 在 cmd.exe 命令行里会被当成控制字符、必须用引号包起来的字符。
_CMD_SPECIAL_CHARS = "&|<>()^"


def needs_command_interpreter(path):
    """判断 ``path`` 是否必须由 ``cmd.exe`` 代为启动。"""
    if os.name != "nt":
        return False
    return os.path.splitext(path)[1].lower() in INTERPRETER_EXTENSIONS


def command_interpreter():
    """返回命令解释器（``cmd.exe``）的路径。"""
    comspec = os.environ.get("COMSPEC") or ""
    if comspec and os.path.isfile(comspec):
        return comspec
    try:
        return resolve("cmd.exe")
    except CommandNotFound:
        return comspec or "cmd.exe"


def _quote_for_cmd(value):
    """按 cmd.exe 的规矩给单个参数加引号。"""
    text = str(value)
    quoted = subprocess.list2cmdline([text])
    if quoted == text and any(ch in text for ch in _CMD_SPECIAL_CHARS):
        # list2cmdline 只关心空格与引号；cmd.exe 还需要引号保护这些控制字符。
        quoted = '"%s"' % text
    return quoted


def build_command_line(path, args=()):
    """返回可直接交给 CreateProcess 的命令行字符串。

    批处理脚本会被包成 ``cmd.exe /D /S /C "<脚本> <参数…>"``：``/D`` 跳过
    AutoRun，``/S`` 让 cmd.exe 稳定地剥掉最外层引号，于是路径里带空格、
    参数里带引号都能原样送达脚本。
    """
    argv = [path] + [str(a) for a in args]
    if not needs_command_interpreter(path):
        return subprocess.list2cmdline(argv)

    inner = " ".join(_quote_for_cmd(item) for item in argv)
    return '"%s" /D /S /C "%s"' % (command_interpreter(), inner)


def run(argv, timeout=None):
    """解析 ``argv[0]`` 并执行，返回 ``subprocess.CompletedProcess``。"""
    if not argv:
        raise ValueError("argv must not be empty")

    path = resolve(argv[0])
    args = [str(a) for a in argv[1:]]

    if needs_command_interpreter(path):
        command = build_command_line(path, args)
    else:
        command = [path] + args

    return subprocess.run(
        command,
        capture_output=True,
        text=True,
        timeout=timeout,
    )


def run_ok(argv, timeout=None):
    """执行并断言成功；返回标准输出（已去掉尾部空白）。"""
    proc = run(argv, timeout=timeout)
    if proc.returncode != 0:
        raise RuntimeError(
            "command %r exited with %d: %s" % (argv[0], proc.returncode, proc.stderr.strip())
        )
    return proc.stdout.strip()
